interface.definition:
#"SYSTEM_SYSRULES_sectionLayout_v1"(
  label: "Interview/Office Visit Availability",
  marginBelow: "STANDARD",
  labelColor: "SECONDARY",
  isCollapsible: true,
  contents: {
    #"SYSTEM_SYSRULES_richTextDisplayField"(
      labelPosition: "COLLAPSED",
      value: #"SYSTEM_SYSRULES_richTextItem_v1"(
        text: "To be completed by Candidate",
        style: "EMPHASIS"
      )
    ),
    #"SYSTEM_SYSRULES_cardLayout"(
      marginBelow: "STANDARD",
      contents: {
        #"SYSTEM_SYSRULES_columnsLayout"(
          columns: {
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: #"SYSTEM_SYSRULES_paragraphField"(
                label: "Interview Date"&char(47)&"Time Availability",
                height: "MEDIUM",
                value: if(
                  #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.interviewAvailability),
                  #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3372378",
                  ri!nomination.interviewAvailability
                ),
                readOnly: true
              )   
            ),
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: #"SYSTEM_SYSRULES_paragraphField"(
                label:"Office Visit Date"&char(47)&"Time Availability", 
                height: "MEDIUM",
                value: if(
                  #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.officeVisitAvailability),
                  #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3372378",
                  ri!nomination.officeVisitAvailability
                ),
                readOnly: true
              )   
            )
          },
          showDividers: true 
        )
      }
    )
  }
)
